#!/usr/bin/env python3
"""Source-only availability and correct honest ell-fiber test for image(W)=P."""
import hashlib,itertools,json,resource,signal,time
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];ID='AMBIENT_B18_NIL_TRANSFER_P_FIBER_PREFLIGHT_20261104_v63';OUT=ROOT/'reports'/ID
def sha(p):
 with p.open('rb')as f:return hashlib.file_digest(f,'sha256').hexdigest()
def main():
 t=time.monotonic();signal.alarm(60);resource.setrlimit(resource.RLIMIT_AS,(2_000_000_000,2_000_000_000));OUT.mkdir(exist_ok=True);pins={}
 def load(st,name='report.json'):
  p=ROOT/'reports'/st/name;pins[str(p.relative_to(ROOT))]=sha(p);return json.loads(p.read_text())
 for st in ['AMBIENT_B18_NIL_CUBE_OBSTRUCTION_REDUCTION','AMBIENT_B18_NIL_DVR_FINITENESS','AMBIENT_B18_CONDUCTOR_TRANSFER512_NIL_CYCLES','AMBIENT_B18_HONEST_NIL_T_OPERATOR','AMBIENT_B18_HONEST_NIL_T_MINIMAL_OPERATOR','AMBIENT_B18_HONEST_NIL_T_FIRST_LINEAR','AMBIENT_B18_COMPARISON_C_GENERIC_DVR_RANK','AMBIENT_B18_REDUCED_COMPARISON_GENERIC_RANK2','AMBIENT_B18_REDUCED_COMPARISON_CBAR_VALUES','AMBIENT_B18_CBAR_LITERAL_RESOLUTION']:
  assert load(st+'_20261104_v63_REVIEW')['all_passed']
 W=load('AMBIENT_B18_CONDUCTOR_TRANSFER512_NIL_CYCLES_20261104_v63','actual-transfer512-H1-cycles-typed-DAG.json')
 H=load('AMBIENT_B18_HONEST_NIL_T_OPERATOR_20261104_v63','actual-honest-Tnil128-972-formal-operator.json')
 Min=load('AMBIENT_B18_HONEST_NIL_T_MINIMAL_OPERATOR_20261104_v63','actual-minimal-Tnil5-849-and-d3-linear-operator.json')
 cycles=W['actual_512_transfer_cycles'];assert len(cycles)==512 and W['normalized_nil_two_basis4_spans_entire_NilE4_as_R0_module']and W['all512_generate_exact_transfer_W_not_all_NilD0']
 assert sorted((c['CA_generator_index'],c['CB_raw_index'],c['normalized_nil_generator_index'],c['normalizer_basis_index'])for c in cycles)==list(itertools.product(range(8),range(8),range(2),range(4)))
 assert all(len(c['literal_H1_cycle44'])==44 and len(c['p_four_actual_R0_components'])==4 for c in cycles)
 assert H['matrix_operator_shapes'][H['matrices']['new_m24_by44']]==[24,44]
 assert H['matrix_operator_shapes'][H['matrices']['Phi44_by128']]==[44,128]
 assert Min['operator_shapes'][Min['matrices']['full_target_projection5_by128']]==[5,128]
 # Pure DVR dimension consequences, not a guessed actual basis.
 # 0→Q→C→Cprime→0 gives Q[ell]→C[ell]→Cprime[ell].
 C_rank,C_fiber,Cp_rank,Cp_fiber,NE_rank,P_rank=4,8,2,4,9,7
 C_tors=C_fiber-C_rank;Cp_tors=Cp_fiber-Cp_rank;assert(C_tors,Cp_tors)==(4,2)
 cases=[]
 for qtor in range(0,C_tors+1):
  image_Ctors=C_tors-qtor
  if image_Ctors>Cp_tors:continue
  assert qtor>=2
  P_image=P_rank-qtor;Q_fiber=2+qtor;assert P_image+Q_fiber==NE_rank
  # ker(NE/ell→C/ell) has length5 independently of qtor.
  F_image=NE_rank-(C_fiber-Cp_fiber);unseen=F_image-P_image;assert F_image==5 and unseen==qtor-2
  cases.append(dict(torsion_generator_count_Q=qtor,kernel_Pfiber_to_NEfiber=qtor,visible_Pfiber_dimension=P_image,Qfiber_dimension=Q_fiber,normalizer_fiber_comparison_kernel_dimension=F_image,extra_Tor_directions_in_that_kernel=unseen))
 assert [c['torsion_generator_count_Q']for c in cases]==[2,3,4]
 for L in range(11,18):assert (L+5)-(L-4)==9 and (L+3)-(L-4)==7
 source_profile=dict(available_512_cycle_sources=[dict(index=c['index'],cycle44_json_pointer=f'/actual_512_transfer_cycles/{c["index"]}/literal_H1_cycle44',normalizer_image_recipe=dict(f_root=c['actual_f_betaA_times_bB'],nil_basis4_components=c['p_four_actual_R0_components']))for c in cycles],
  transfer_namespace='new_typed_scalar_nodes; all explicit foreign source namespaces retained',
  normalized_image='psi(w)=f*(n_alpha e_gamma), a four-component C expression',
  honest_Tnil_image_recipe='Restrict actual cycle z44 to ell0; set v=m z; apply the ORIGINAL canonical three-sector Koszul homotopy to v, yielding b84 with d2 b=v; (z,b) is an honest128 representative because Phi(z,b)=z. Apply the pinned minimal5×128 target projection.',
  homotopy_not_S_linear=True,apply_homotopy_to_each_original_actual512_function_before_linear_extension=True,
  honest_m_node=H['matrices']['new_m24_by44'],honest_Phi_node=H['matrices']['Phi44_by128'],minimal_projection_node=Min['matrices']['full_target_projection5_by128'],
  no_homotopy_or512_fiber_values_constructed=True,
  missing_honest_Kfiber='Image of actual K/ellK inside N/ellN⊂Tnil. The whole old specialized comparison T_K contains C[ell] as well, so it cannot replace K/ellK.',
  alternative_missing_data='Actual7 D-basis lifts of P and exact regular coordinates for all512 psi(W) images in that frame, including lattice/ell-divisibility identities.',
  all512_R0_module_generators_suffice_because='N_E is R0-generated by two nil generators times four C-basis vectors; transfer is R0-linear and D0 action absorbs through C multiplication.',
  no_fresh_source_jet_or_numeric_projection_run=True)
 theorem=dict(known_exact_sequences=['0→K→N→P→0, with P D-free7','0→P→N_E→Q→0, Q=ker(C→Cprime)','0→Q→C→Cprime→0','0→N/ellN→Tnil→Cprime[ell]→0'],
  W_surjects_P_iff='N=K+W',W_surjects_P_implies='N^3=0, because K^3=0 and every triple containing W vanishes',
  safe_finite_Nakayama_test='P/(psi(W)+ellP)=0 iff P=psi(W)',
  S9_definition='Tnil / image(K/ellK)',S9_length=9,S9_sequence='0→P/ellP(dim7)→S9→Cprime[ell](dim2)→0',
  correct_complete_test='length(S9 / image(actual512 W))=2 iff P=psi(W); the image is the full R0/(ell)-submodule, not just its origin fiber',
  definitive_noninjectivity_cases=cases,
  impossible_normalizer_fiber_shortcut='P/ellP(dim7)→N_E/ellN_E(dim9) has kernel dimension2..4, so rank7 in the latter is impossible and cannot be used as a criterion.',
  whole_old_T_quotient_wrong='T_K has lengthL whereas K/ellK has lengthL−4. Replacing K/ellK with allT_K discards four extra torsion/edge directions and yields a different length5 quotient.',
  not_inferred=['P=psi(W)','gamma=0','beta=0','nilcubezero','actualQ torsion count is one chosen2/3/4','P embedding primitive or saturated in N_E','all512 origin values suffice','m^k annihilates cube from a fiber computation'],
  source_availability=source_profile)
 p=OUT/'honest-nine-dimensional-P-coverage-source-profile.json';p.write_text(json.dumps(theorem,indent=2)+'\n')
 for x in[Path(__file__),ROOT/f'research/notes/{ID}.md']:pins[str(x.relative_to(ROOT))]=sha(x)
 rep=dict(id=ID,all_passed=True,frozen=True,source_only=True,honest_Pcoverage_quotient_length9=True,P_to_normalized_ellfiber_kernel_dimension_bounds=[2,4],W_coverage_would_imply_nilcubezero=True,all512_actual_source_paths_bound=True,actual_Wfiber_values_or_Kfiber_injection_NOT_computed=True,no_new_source_jet_scalar_values=True,input_sha256=pins,evidence_sha256={p.name:sha(p)for p in OUT.iterdir()if p.is_file()and p.name!='report.json'},seconds=time.monotonic()-t)
 (OUT/'report.json').write_text(json.dumps(rep,indent=2)+'\n');signal.alarm(0);print(json.dumps({k:v for k,v in rep.items()if k not in['input_sha256','evidence_sha256']},indent=2))
if __name__=='__main__':main()
